"""Prints packages/contract/src/generated/loginSites.ts: every site the installed yt-dlp can sign in
to with a username and password, by its netrc machine name (what `--netrc` looks up).

Run by `mise run gen:login-sites` inside the image, with the image's own Python (`-I`), so the list
is the pinned yt-dlp's. YouTube has a machine name but refuses passwords (cookies only), so it is
left out. The smoke test compares this output with the committed file.
"""

import warnings

from yt_dlp.extractor import gen_extractor_classes

EXCLUDED = {"youtube"}

HEADER = """\
// Generated by `mise run gen:login-sites` from the pinned yt-dlp: every site it can sign in to with
// a username and password, by its netrc machine name. YouTube is left out (cookies only). Do not
// edit; regenerate after a yt-dlp bump (the image smoke test fails until you do).
"""


def main() -> None:
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        machines = {
            ie._NETRC_MACHINE
            for ie in gen_extractor_classes()
            if ie._NETRC_MACHINE and ie._NETRC_MACHINE not in EXCLUDED
        }
    lines = "".join(f'  "{machine}",\n' for machine in sorted(machines))
    print(f"{HEADER}export const LOGIN_SITES = [\n{lines}] as const;", end="\n")


main()
